"""Pack Home artwork at its display sizes; PNGs take precedence over SVGs."""
from pathlib import Path
import io

from PIL import Image
import resvg_py

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / 'assets_local/home-icons'
OUTPUT = ROOT / 'src/apps_local/ui/HomeIcons.h'


def generate(source=SOURCE, output=OUTPUT, namespace='homeicons', sizes=(26, 32, 40, 64), inset=4):
    lines = ['#pragma once', '#include <Icon.h>', '',
             '// Generated by tools_local/navigation_art/generate_home.py.',
             '// clang-format off', f'namespace {namespace} {{']
    sources = {p.stem: p for p in source.glob('*.svg')}
    sources.update({p.stem: p for p in source.glob('*.png')})
    for stem, path in sorted(sources.items()):
        for size in sizes:
            if path.suffix == '.png':
                original = Image.open(path).convert('RGBA')
                white = Image.new('RGBA', original.size, 'white')
                image = Image.alpha_composite(white, original).convert('L')
            else:
                raw = resvg_py.svg_to_bytes(svg_path=str(path), width=512, height=512, background='white')
                image = Image.open(io.BytesIO(raw)).convert('L')
            box = image.point(lambda v: 255 if v < 180 else 0).getbbox()
            if box is None:
                raise ValueError('Empty icon: ' + path.name)
            image = image.crop(box)
            image.thumbnail((size - inset, size - inset), Image.Resampling.LANCZOS)
            canvas = Image.new('L', (size, size), 255)
            canvas.paste(image, ((size - image.width) // 2, (size - image.height) // 2))
            bits = []
            ys = []
            for y in range(size):
                for x in range(0, size, 8):
                    value = 0
                    for bit in range(8):
                        white = x + bit >= size or canvas.getpixel((x + bit, y)) >= 160
                        value |= int(white) << (7 - bit)
                        if not white:
                            ys.append(y)
                    bits.append(value)
            name = path.stem + str(size)
            lines.append(f'inline constexpr uint8_t {name}Bits[] = {{')
            lines.extend('  ' + ','.join(f'0x{n:02x}' for n in bits[i:i+24]) + ','
                         for i in range(0, len(bits), 24))
            lines.extend(['};', f'inline constexpr freeink::Icon {name}{{{size}, {size}, {round(sum(ys)/len(ys))}, {name}Bits}};'])
        if len(sizes) > 1:
            choices = ''.join(f'size <= {size} ? {stem}{size} : ' for size in sizes[:-1]) + f'{stem}{sizes[-1]}'
            lines.extend([f'inline constexpr const freeink::Icon& {stem}(int size) {{',f'  return {choices};','}'])
    lines.extend([f'}}  // namespace {namespace}', '// clang-format on', ''])
    output.write_text('\n'.join(lines), 'utf8')


if __name__ == '__main__':
    generate()
